<?php require dirname(__DIR__).'/app/bootstrap.php';
if(current_user()){header('Location: '.path('admin/index.php'));exit;}$sent=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$email=strtolower(trim((string)($_POST['email']??'')));$key=hash('sha256','reset|'.$email.'|'.($_SERVER['REMOTE_ADDR']??''));$window=db_is_sqlite()?"datetime('now','-30 minutes')":'DATE_SUB(NOW(),INTERVAL 30 MINUTE)';$count=(int)(query_one('SELECT COUNT(*) AS n FROM login_attempts WHERE identifier_hash=? AND attempted_at>'.$window,[$key])['n']??0);if($count<5){db()->prepare('INSERT INTO login_attempts(identifier_hash) VALUES (?)')->execute([$key]);$user=filter_var($email,FILTER_VALIDATE_EMAIL)?query_one('SELECT id,email FROM users WHERE email=? AND active=1',[$email]):null;$dispatcher=cfg('password_reset_dispatcher');if($user&&is_callable($dispatcher)){try{$token=PasswordResetService::issue((int)$user['id']);$url=absolute_url('admin/reset-password.php?token='.rawurlencode($token));$dispatcher((string)$user['email'],$url);}catch(Throwable $e){db()->prepare('DELETE FROM password_reset_tokens WHERE user_id=? AND used_at IS NULL')->execute([(int)$user['id']]);error_log('Password reset delivery failed.');}}}audit_log('password_reset_requested','user',0);$sent=true;}
